      }
    }
    __syncthreads();
    buf ^= 1;
  }
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    int mi = m0 + i;
    if (mi >= m_lim) continue;
    int gm = m_start + mi;
    #pragma unroll
    for (int j = 0; j < 4; ++j) {
      int ni = n0 + j;
      if (ni >= n_lim) continue;
      int gn = n_start + ni;
      atomicAdd(C + (int64_t)gm * N + gn, acc[i][j]);
    }
  }
